;; Generated by LawSpec. Do not edit.
(ns lawspec.check
  "LawSpec's generators on test.check. A generator of the law cases becomes a
  test.check generator of rose trees: the root is a case drawn from
  test.check's random source and size, and its children are the smaller
  cases LawSpec can make again, so a shrink never leaves a refinement.
  quick-check runs a law's property and throws an AssertionError naming the
  smallest failing case and the seed that repeats the run."
  (:require [clojure.test.check :as tc]
            [clojure.test.check.generators :as gen]
            [clojure.test.check.properties :as prop]
            [clojure.test.check.random :as random]
            [clojure.test.check.rose-tree :as rose])
  (:import (java.util Iterator)
           (java.util.function Predicate)
           (lawspec.testing.check Draws$Case Generator)))

(defn- tree
  "The rose tree of a case: its value, and lazily the trees of its shrinks."
  [^Draws$Case c]
  (rose/make-rose (.value c) (map tree (iterator-seq (.shrinks c)))))

(defn generator
  "A test.check generator of a LawSpec generator's cases."
  [^Generator g]
  (gen/->Generator
   (fn [rnd size]
     (tree (Draws$Case/generate g (random/rand-long rnd) (int size))))))

(defn- message [result]
  (let [shrunk (:shrunk result)
        failure (:result shrunk)]
    (str "Property falsified after " (:num-tests result) " cases (seed " (:seed result)
         "; LAWSPEC_SEED=" (:seed result) " repeats the run)\n"
         "Smallest case: " (pr-str (first (:smallest shrunk)))
         (when (instance? Throwable failure) (str "\n" (.getMessage ^Throwable failure))))))

(defn quick-check
  "Checks a property of a generator's values with test.check."
  [^Generator g ^Predicate property iterations seed]
  (let [checked (prop/for-all* [(generator g)] (fn [value] (.test property value)))
        result (apply tc/quick-check iterations checked :max-size 100 (when seed [:seed seed]))]
    (when-not (:pass? result)
      (let [failure (:result (:shrunk result))]
        (throw (AssertionError. ^String (message result)
                                ^Throwable (when (instance? Throwable failure) failure)))))
    nil))
